from abc import ABC, abstractmethod
from pathlib import Path


class ConfigFileGeneric(ABC):

    @abstractmethod
    def fetch_content(self, *args, **kwargs):
        pass

    @abstractmethod
    def to_file(self, *args, **kwargs):
        pass


class TextBasedConfigFile(ConfigFileGeneric):

    @abstractmethod
    def __init__(self, filename, section_separator='\n'):
        self._section_separator = section_separator
        self._file_content = ''
        self._filename = filename
        self._sections = []

    def fetch_content(self, *args, **kwargs):
        sections_content = []
        for section in self._sections:
            section_content = section.generate_section_content(*args, **kwargs)
            if section_content:
                sections_content.append(section_content)

        self._file_content = self._section_separator.join(sections_content)
#        self._file_content = self._section_separator.join(
#            section.generate_section_content(*args, **kwargs) for section in self._sections
#        )

    def to_file(self, output_dir, *args, **kwargs):
        self.fetch_content(*args, **kwargs)

        filepath = Path(output_dir) / self._filename
        with filepath.open(mode='w', encoding='utf-8') as f:
            f.write(self._file_content)
